let file = """{"version":3,"file":"useTypeformEmbed-C46oxorf.js","names":[],"sources":["../../packages/shared-frontend-utils/src/loadExternalScript.ts","../../src/platform/surveys/useTypeformEmbed.ts"],"sourcesContent":["const POLL_INTERVAL_MS = 50\n\n/**\n * Returns a singleton loader for an external script. `getReady` should return\n * the resolved value when the script's global is available, or `null` when not.\n * The returned function caches the in-flight Promise so concurrent callers share\n * one load, and resets on failure so a later caller can retry.\n */\nexport function createScriptLoader<T>(\n  src: string,\n  getReady: () => T | null,\n  timeoutMs = 10_000\n): () => Promise<T> {\n  let scriptPromise: Promise<T> | null = null\n\n  return function loadScript(): Promise<T> {\n    if (scriptPromise) return scriptPromise\n\n    scriptPromise = new Promise<T>((resolve, reject) => {\n      let settled = false\n      let cancelPoll: (() => void) | undefined\n\n      function trySettle(fn: () => void) {\n        if (settled) return\n        settled = true\n        fn()\n      }\n\n      const ready = getReady()\n      if (ready !== null) {\n        resolve(ready)\n        return\n      }\n\n      const existing = document.querySelector<HTMLScriptElement>(\n        `script[src=\"${src}\"]`\n      )\n\n      function startPoll(onSuccess: () => void): () => void {\n        const pollId = window.setInterval(() => {\n          const value = getReady()\n          if (value !== null) {\n            window.clearInterval(pollId)\n            onSuccess()\n            trySettle(() => resolve(value))\n          }\n        }, POLL_INTERVAL_MS)\n        return () => window.clearInterval(pollId)\n      }\n\n      if (existing) {\n        // load/error may have already fired on the pre-existing tag; poll for readiness\n        const timeoutId = window.setTimeout(() => {\n          cancelPoll?.()\n          trySettle(() => {\n            scriptPromise = null\n            reject(new Error(`Script load timed out: ${src}`))\n          })\n        }, timeoutMs)\n        cancelPoll = startPoll(() => window.clearTimeout(timeoutId))\n        return\n      }\n\n      const scriptEl = document.createElement('script')\n\n      const timeoutId = window.setTimeout(() => {\n        cancelPoll?.()\n        scriptEl.remove()\n        trySettle(() => {\n          scriptPromise = null\n          reject(new Error(`Script load timed out: ${src}`))\n        })\n      }, timeoutMs)\n\n      scriptEl.addEventListener(\n        'load',\n        () => {\n          if (settled) return\n          const value = getReady()\n          if (value !== null) {\n            window.clearTimeout(timeoutId)\n            trySettle(() => resolve(value))\n          } else {\n            // global may arrive asynchronously after load; poll under the shared timeout\n            cancelPoll = startPoll(() => window.clearTimeout(timeoutId))\n          }\n        },\n        { once: true }\n      )\n      scriptEl.addEventListener(\n        'error',\n        () => {\n          window.clearTimeout(timeoutId)\n          scriptEl.remove()\n          trySettle(() => {\n            scriptPromise = null\n            reject(new Error(`Script failed to load: ${src}`))\n          })\n        },\n        { once: true }\n      )\n\n      scriptEl.src = src\n      scriptEl.async = true\n      document.head.appendChild(scriptEl)\n    })\n\n    return scriptPromise\n  }\n}\n","import { whenever } from '@vueuse/core'\nimport type { MaybeRefOrGetter, Ref } from 'vue'\nimport { computed, ref, toValue } from 'vue'\n\nimport { createScriptLoader } from '@comfyorg/shared-frontend-utils/loadExternalScript'\n\nconst TYPEFORM_SRC = 'https://embed.typeform.com/next/embed.js'\nconst VALID_ID_PATTERN = /^[A-Za-z0-9]+$/\n\ninterface TypeformGlobal {\n  load?: () => void\n}\n\ndeclare global {\n  interface Window {\n    tf?: TypeformGlobal\n  }\n}\n\n/** Pure validator for Typeform form IDs. Exported so feature sites can\n *  gate rendering before mounting the embed container. */\nexport function isTypeformIdValid(id: string | undefined | null): boolean {\n  return !!id && VALID_ID_PATTERN.test(id)\n}\n\nconst loadTypeformScript = createScriptLoader(TYPEFORM_SRC, () =>\n  typeof window.tf?.load === 'function' ? window.tf : null\n)\n\nfunction ensureScriptLoaded(): Promise<TypeformGlobal> {\n  return loadTypeformScript()\n}\n\n/**\n * Loads the Typeform embed script on first consumer mount and exposes\n * validation + error state for an inline form container. After the\n * script is ready, `window.tf.load()` is called each time a new\n * container appears so Typeform re-scans for the new `data-tf-widget`\n * element — the embed's DOMContentLoaded auto-scan only runs once and\n * its MutationObserver does not reliably catch elements added by later\n * consumers (e.g. a second popover opening later in the session).\n * `load()` with `forceReload: false` is idempotent for already-\n * initialized elements.\n */\nexport function useTypeformEmbed(\n  typeformRef: Ref<HTMLElement | null>,\n  typeformIdInput: MaybeRefOrGetter<string | undefined>\n) {\n  const typeformError = ref(false)\n\n  const isValidTypeformId = computed(() =>\n    isTypeformIdValid(toValue(typeformIdInput))\n  )\n\n  whenever(typeformRef, async () => {\n    try {\n      await ensureScriptLoaded()\n      const tf = window.tf\n      if (typeof tf?.load !== 'function') {\n        console.error('Typeform API unavailable after script load')\n        typeformError.value = true\n        return\n      }\n      tf.load()\n    } catch (err) {\n      console.error('[useTypeformEmbed]', err)\n      typeformError.value = true\n    }\n  })\n\n  return {\n    typeformError,\n    isValidTypeformId\n  }\n}\n"],"mappings":"0JAAA,IAAM,EAAmB,GAQzB,SAAgB,mBACd,EACA,EACA,EAAY,IACM,CAClB,IAAI,EAAmC,KAEvC,OAAO,SAAS,YAAyB,CA4FvC,OA3FI,IAEJ,EAAgB,IAAI,SAAY,EAAS,IAAW,CAClD,IAAI,EAAU,GACV,EAEJ,SAAS,UAAU,EAAgB,CAC7B,IACJ,EAAU,GACV,EAAG,E